import { ProjectRepository } from '../../domain/project/ProjectRepository';
import { TaskRepository } from '../../domain/task/TaskRepository';
import { UserRepository } from '../../domain/user/UserRepository';
import { InMemoryProjectRepository } from '../persistence/InMemoryProjectRepository';
import { InMemoryTaskRepository } from '../persistence/InMemoryTaskRepository';
import { InMemoryUserRepository } from '../persistence/InMemoryUserRepository';

export interface Repositories {
  projects: ProjectRepository;
  tasks: TaskRepository;
  users: UserRepository;
}

export function createRepositories(): Repositories {
  return {
    projects: new InMemoryProjectRepository(),
    tasks: new InMemoryTaskRepository(),
    users: new InMemoryUserRepository(),
  };
}

